  # ─────────────────────────────────────────────────────────────────────────
  # TI-1446 — PG metrics fan-out. 4 tipos de alertas × 5 envs = 20 rules.
  # Métricas scrapeadas desde postgres_exporter v0.17.1 en cada DB VM
  # (loopback :9187) via Ops Agent prometheus receiver → Cloud Monitoring
  # (resource type prometheus_target, metric prefix prometheus.googleapis.com).
  # Datasource: cloud-monitoring-main. Scope variable via projectName según
  # local.pg_envs. Cada rule tiene labels.env={prod,bi,sha,qa,staging} para
  # routing en alert-receiver. Ver databases/vm/files/monitoring/README.md.
  # ─────────────────────────────────────────────────────────────────────────

  # Rule 10 × 5 envs — PG idle-in-tx leak por aplicación (P0 prod, P1 non-prod)
  # ─────────────────────────────────────────────────────────────────────────
  # Conexiones 'idle in transaction' por application_name. Cada idle-in-tx
  # tiene locks/snapshots activos y bloquea VACUUM + escala row bloat.
  # Root-cause: app no cierra tx tras error, gunicorn worker timeout, pool mal.
  # Observado 2026-04-23: orders-domain + services-domain (advisory_xact_lock).
  dynamic "rule" {
    for_each = local.pg_envs
    content {
      name      = "PG idle-in-tx leak [${rule.key}]"
      for       = "5m"
      condition = "C"

      data {
        ref_id         = "A"
        datasource_uid = "cloud-monitoring-main"
        relative_time_range {
          from = 600
          to   = 0
        }
        model = jsonencode({
          refId     = "A"
          queryType = "metrics"
          metricQuery = {
            projectName        = rule.value
            metricType         = "prometheus.googleapis.com/pg_idle_in_tx_by_app_count/gauge"
            alignmentPeriod    = "cloud-monitoring-auto"
            perSeriesAligner   = "ALIGN_MEAN"
            crossSeriesReducer = "REDUCE_MAX"
            groupBys = [
              "metric.label.instance_name",
              "metric.label.application_name",
            ]
            aliasBy    = "{{metric.label.instance_name}} | {{metric.label.application_name}}"
            editorMode = "visual"
          }
        })
      }

      data {
        ref_id         = "C"
        datasource_uid = "__expr__"
        relative_time_range {
          from = 0
          to   = 0
        }
        model = jsonencode({
          type       = "threshold"
          expression = "A"
          refId      = "C"
          conditions = [{
            evaluator = { params = [10], type = "gt" }
            operator  = { type = "and" }
            query     = { params = ["C"] }
            reducer   = { type = "last" }
            type      = "query"
          }]
        })
      }

      labels = {
        severity = rule.key == "prod" ? "P0" : "P1"
        team     = "infra"
        env      = rule.key
      }

      annotations = {
        summary     = "[${rule.key}] PG idle-in-tx >10 en {{ $labels.instance_name }} app={{ $labels.application_name }}"
        description = "Aplicación {{ $labels.application_name }} tiene >10 conexiones 'idle in transaction' sostenido 5min sobre instance {{ $labels.instance_name }} (env=${rule.key}). Bloquea VACUUM y provoca bloat/locks. Investigar: tx no cerradas por error, gunicorn worker timeout, pool saturado."
      }

      no_data_state  = "OK"
      exec_err_state = "OK"
      is_paused      = false
    }
  }

  # ─────────────────────────────────────────────────────────────────────────
  # Rule 11 × 5 envs — PG connections saturation > 80% (P1)
  # ─────────────────────────────────────────────────────────────────────────
  # Ratio current_connections / max_connections. Baseline lms-db prod: 0.69.
  # Umbral 0.80. A 0.90 falta capacidad para reintentos o spikes.
  dynamic "rule" {
    for_each = local.pg_envs
    content {
      name      = "PG connections saturation > 80% [${rule.key}]"
      for       = "5m"
      condition = "C"

      data {
        ref_id         = "A"
        datasource_uid = "cloud-monitoring-main"
        relative_time_range {
          from = 600
          to   = 0
        }
        model = jsonencode({
          refId     = "A"
          queryType = "metrics"
          metricQuery = {
            projectName        = rule.value
            metricType         = "prometheus.googleapis.com/pg_connection_saturation_saturation_ratio/gauge"
            alignmentPeriod    = "cloud-monitoring-auto"
            perSeriesAligner   = "ALIGN_MEAN"
            crossSeriesReducer = "REDUCE_MEAN"
            groupBys = [
              "metric.label.instance_name",
            ]
            aliasBy    = "{{metric.label.instance_name}}"
            editorMode = "visual"
          }
        })
      }

      data {
        ref_id         = "C"
        datasource_uid = "__expr__"
        relative_time_range {
          from = 0
          to   = 0
        }
        model = jsonencode({
          type       = "threshold"
          expression = "A"
          refId      = "C"
          conditions = [{
            evaluator = { params = [0.80], type = "gt" }
            operator  = { type = "and" }
            query     = { params = ["C"] }
            reducer   = { type = "last" }
            type      = "query"
          }]
        })
      }

      labels = {
        severity = "P1"
        team     = "infra"
        env      = rule.key
      }

      annotations = {
        summary     = "[${rule.key}] PG connection saturation > 80% en {{ $labels.instance_name }}"
        description = "Saturación de conexiones a {{ $labels.instance_name }} (env=${rule.key}) sostenida 5min. Investigar qué app concentra conexiones via postgres-deep. Considerar pgbouncer o aumentar max_connections si es growth legítimo."
      }

      no_data_state  = "OK"
      exec_err_state = "OK"
      is_paused      = false
    }
  }

  # ─────────────────────────────────────────────────────────────────────────
  # Rule 12 × 5 envs — PG replication replay lag > 30s (P1)
  # ─────────────────────────────────────────────────────────────────────────
  # replay_lag afecta read-after-write. Baseline prod 2026-04-23: 0.04s-0.06s.
  # Umbral 30s. Instances sin replicas no reportan esta métrica → no_data=OK.
  dynamic "rule" {
    for_each = local.pg_envs
    content {
      name      = "PG replication replay lag > 30s [${rule.key}]"
      for       = "5m"
      condition = "C"

      data {
        ref_id         = "A"
        datasource_uid = "cloud-monitoring-main"
        relative_time_range {
          from = 600
          to   = 0
        }
        model = jsonencode({
          refId     = "A"
          queryType = "metrics"
          metricQuery = {
            projectName        = rule.value
            metricType         = "prometheus.googleapis.com/pg_replication_status_replay_lag_seconds/gauge"
            alignmentPeriod    = "cloud-monitoring-auto"
            perSeriesAligner   = "ALIGN_MAX"
            crossSeriesReducer = "REDUCE_MAX"
            groupBys = [
              "metric.label.instance_name",
              "metric.label.replica_addr",
            ]
            aliasBy    = "{{metric.label.instance_name}} → {{metric.label.replica_addr}}"
            editorMode = "visual"
          }
        })
      }

      data {
        ref_id         = "C"
        datasource_uid = "__expr__"
        relative_time_range {
          from = 0
          to   = 0
        }
        model = jsonencode({
          type       = "threshold"
          expression = "A"
          refId      = "C"
          conditions = [{
            evaluator = { params = [30], type = "gt" }
            operator  = { type = "and" }
            query     = { params = ["C"] }
            reducer   = { type = "last" }
            type      = "query"
          }]
        })
      }

      labels = {
        severity = "P1"
        team     = "infra"
        env      = rule.key
      }

      annotations = {
        summary     = "[${rule.key}] PG replica {{ $labels.replica_addr }} replay_lag > 30s (primary {{ $labels.instance_name }})"
        description = "Replica {{ $labels.replica_addr }} atrasada >30s aplicando WAL desde primary {{ $labels.instance_name }} (env=${rule.key}). Afecta read-after-write. Investigar IO/CPU en replica, red con primary, queries largas bloqueando recovery."
      }

      no_data_state  = "OK"
      exec_err_state = "OK"
      is_paused      = false
    }
  }

  # ─────────────────────────────────────────────────────────────────────────
  # Rule 13 × 5 envs — PG blocking queries > 2min (P0 prod, P1 non-prod)
  # ─────────────────────────────────────────────────────────────────────────
  # Count de queries esperando lock > 120s. Cualquier valor >0 ya indica
  # contención real (advisory locks, row locks, DDL pending). Ventana 2m
  # para reaccionar antes del stampede de timeouts.
  dynamic "rule" {
    for_each = local.pg_envs
    content {
      name      = "PG blocking queries > 2min [${rule.key}]"
      for       = "2m"
      condition = "C"

      data {
        ref_id         = "A"
        datasource_uid = "cloud-monitoring-main"
        relative_time_range {
          from = 600
          to   = 0
        }
        model = jsonencode({
          refId     = "A"
          queryType = "metrics"
          metricQuery = {
            projectName        = rule.value
            metricType         = "prometheus.googleapis.com/pg_blocking_queries_blocked_over_120s/gauge"
            alignmentPeriod    = "cloud-monitoring-auto"
            perSeriesAligner   = "ALIGN_MAX"
            crossSeriesReducer = "REDUCE_MAX"
            groupBys = [
              "metric.label.instance_name",
            ]
            aliasBy    = "{{metric.label.instance_name}}"
            editorMode = "visual"
          }
        })
      }

      data {
        ref_id         = "C"
        datasource_uid = "__expr__"
        relative_time_range {
          from = 0
          to   = 0
        }
        model = jsonencode({
          type       = "threshold"
          expression = "A"
          refId      = "C"
          conditions = [{
            evaluator = { params = [0], type = "gt" }
            operator  = { type = "and" }
            query     = { params = ["C"] }
            reducer   = { type = "last" }
            type      = "query"
          }]
        })
      }

      labels = {
        severity = rule.key == "prod" ? "P0" : "P1"
        team     = "infra"
        env      = rule.key
      }

      annotations = {
        summary     = "[${rule.key}] PG queries bloqueadas >2min en {{ $labels.instance_name }}"
        description = "Hay {{ $value }} queries esperando lock >120s en {{ $labels.instance_name }} (env=${rule.key}). Contención real (advisory locks, row locks, DDL pending). Escalar a postgres-deep: pg_blocking_pids() + pg_stat_activity WHERE wait_event_type='Lock'. Pattern observado prod 2026-04-23: services-domain con pg_advisory_xact_lock + gunicorn timeouts."
      }

      no_data_state  = "OK"
      exec_err_state = "OK"
      is_paused      = false
    }
  }
}

